"""Witch (hovering spell-caster) and undead spider (poison skull) pixel art, user-supplied. All frames face left."""
import base64
import zlib
import pygame

PAL = '13131333984b5d5d5d93388f6224613d3d3d3b1443e69c69000000f6ca9f5ac54ff9e6cf99e65f03193f858585d4a87ef7eedc654d362e2e27b4b4b4bf6f4a1e6f50ffffffc7cfdd134c4c657392'
ANIMS = {'w_idle': (68, 84, 6, ''), 'w_move': (68, 84, 6, ''), 'w_attack': (68, 84, 6, ''), 'w_death': (68, 84, 7, ''), 'w_bolt': (32, 12, 9, ''), 's_idle': (107, 47, 13, ''), 's_walk': (107, 47, 8, ''), 's_attack': (107, 47, 16, '')}
_PAL = None
_CACHE = {}


def ws_frame(name, i, scale=1.0):
  global _PAL
  w, h, n, data = ANIMS[name]
  i %= n
  k = (name, i, scale)
  s = _CACHE.get(k)
  if s is None:
    if _PAL is None:
      _PAL = [None] + [tuple(int(PAL[j + q:j + q + 2], 16) for q in (0, 2, 4)) for j in range(0, len(PAL), 6)]
    raw = _CACHE.get((name, 'raw'))
    if raw is None:
      raw = _CACHE[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = i * w * h
    for p in range(w * h):
      v = raw[base + p]
      if v:
        s.set_at((p % w, p // w), _PAL[v] + (255,))
    if scale != 1.0:
      s = pygame.transform.scale(s, (int(w * scale), int(h * scale)))
    _CACHE[k] = s
  return s


def ws_count(name):
  return ANIMS[name][2]
